INSERT INTO questions (exam_id, body, options, answer, explanation) SELECT (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'ifrs' AND e.kind = 'level' AND e.after_level = 1), 'أنهي بند مايدخلش في تكلفة أصل مطور داخليًا؟', '["خامات استخدمت في التطوير","أجور فريق التطوير","رسوم تسجيل حق قانوني","تحميل من المصاريف الإدارية العامة"]', 3, 'المصاريف الإدارية العامة مش مباشرة (IAS 38.66–67).' WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'ifrs' AND e.kind = 'level' AND e.after_level = 1) AND body = 'أنهي بند مايدخلش في تكلفة أصل مطور داخليًا؟'); INSERT INTO questions (exam_id, body, options, answer, explanation) SELECT (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'ifrs' AND e.kind = 'level' AND e.after_level = 1), 'حسب IAS 2، المخزون بيتقاس بـ:', '["التكلفة دايمًا","القيمة العادلة","سعر البيع","التكلفة أو صافي القيمة القابلة للتحقق أيهما أقل"]', 3, 'IAS 2.9.' WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'ifrs' AND e.kind = 'level' AND e.after_level = 1) AND body = 'حسب IAS 2، المخزون بيتقاس بـ:'); INSERT INTO questions (exam_id, body, options, answer, explanation) SELECT (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'ifrs' AND e.kind = 'level' AND e.after_level = 1), 'بضاعة سعرها 150,000 بخصم تجاري 4%، وجمارك 7,500، ونقل للمخزن 3,500، وضريبة قيمة مضافة قابلة للخصم، وتخزين بعد الاستلام 1,200، وعمولة بيع 2,000. تكلفة المخزون:', '["155,000 جنيه","161,000 جنيه","156,200 جنيه","158,200 جنيه"]', 0, '144,000 + 7,500 + 3,500 = 155,000. التخزين بعد الاستلام والعمولة مايدخلوش (IAS 2.11 و2.16).' WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'ifrs' AND e.kind = 'level' AND e.after_level = 1) AND body = 'بضاعة سعرها 150,000 بخصم تجاري 4%، وجمارك 7,500، ونقل للمخزن 3,500، وضريبة قيمة مضافة قابلة للخصم، وتخزين بعد الاستلام 1,200، وعمولة بيع 2,000. تكلفة المخزون:'); INSERT INTO questions (exam_id, body, options, answer, explanation) SELECT (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'ifrs' AND e.kind = 'level' AND e.after_level = 1), '500 وحدة تكلفة الوحدة 70. سعر البيع المتوقع 80، وتكاليف إكمال 12، وتكاليف بيع 6. التخفيض الكلي:', '["6,000 جنيه","3,000 جنيه","4,000 جنيه","صفر"]', 2, 'NRV = 80 − 12 − 6 = 62. التخفيض = (70 − 62) × 500 = 4,000.' WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'ifrs' AND e.kind = 'level' AND e.after_level = 1) AND body = '500 وحدة تكلفة الوحدة 70. سعر البيع المتوقع 80، وتكاليف إكمال 12، وتكاليف بيع 6. التخفيض الكلي:'); INSERT INTO questions (exam_id, body, options, answer, explanation) SELECT (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'ifrs' AND e.kind = 'level' AND e.after_level = 1), '3 أصناف: أ (تكلفة 10,000 وNRV 14,000)، ب (تكلفة 8,000 وNRV 6,500)، ج (تكلفة 5,000 وNRV 5,200). قيمة المخزون:', '["22,000 جنيه","23,000 جنيه","25,700 جنيه","21,500 جنيه"]', 3, 'صنف بصنف: 10,000 + 6,500 + 5,000 = 21,500 (IAS 2.29).' WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'ifrs' AND e.kind = 'level' AND e.after_level = 1) AND body = '3 أصناف: أ (تكلفة 10,000 وNRV 14,000)، ب (تكلفة 8,000 وNRV 6,500)، ج (تكلفة 5,000 وNRV 5,200). قيمة المخزون:'); INSERT INTO questions (exam_id, body, options, answer, explanation) SELECT (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'ifrs' AND e.kind = 'level' AND e.after_level = 1), 'خامات سعر السوق بتاعها نزل تحت تكلفتها، بس المنتج التام اللي هتدخل فيه هيتباع بربح. الخامات:', '["تتخفض لسعر السوق","تفضل بالتكلفة","تتسجل بالقيمة العادلة","تتشال من المخزون"]', 1, 'IAS 2.32