ND e.after_level = 1), 'بنفس بيانات السؤال السابق، مخزون آخر المدة بالمتوسط المرجح الدوري:', '["5,250 جنيه","4,500 جنيه","5,775 جنيه","4,950 جنيه"]', 3, 'المتوسط = 16,500 ÷ 500 = 33. الباقي 150 × 33 = 4,950.' WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'ifrs' AND e.kind = 'level' AND e.after_level = 1) AND body = 'بنفس بيانات السؤال السابق، مخزون آخر المدة بالمتوسط المرجح الدوري:'); INSERT INTO questions (exam_id, body, options, answer, explanation) SELECT (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'ifrs' AND e.kind = 'level' AND e.after_level = 1), 'أنهي طريقة تسعير ممنوعة حسب IFRS؟', '["FIFO","المتوسط المرجح","LIFO","التمييز العيني"]', 2, 'LIFO مش ضمن الطرق المسموحة في IAS 2 من مراجعة 2003.' WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'ifrs' AND e.kind = 'level' AND e.after_level = 1) AND body = 'أنهي طريقة تسعير ممنوعة حسب IFRS؟'); INSERT INTO questions (exam_id, body, options, answer, explanation) SELECT (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'ifrs' AND e.kind = 'level' AND e.after_level = 1), 'طريقة التمييز العيني (Specific identification) إجبارية في حالة:', '["كل أنواع المخزون","لما الأسعار تزيد","الأصناف اللي مش بتبدل بعضها أو المنتجة لمشروع محدد","الشركات الصغيرة بس"]', 2, 'IAS 2.23.' WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'ifrs' AND e.kind = 'level' AND e.after_level = 1) AND body = 'طريقة التمييز العيني (Specific identification) إجبارية في حالة:'); INSERT INTO questions (exam_id, body, options, answer, explanation) SELECT (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'ifrs' AND e.kind = 'level' AND e.after_level = 1), 'مخزون اتخفض 30,000 السنة اللي فاتت ولسه موجود، والنهاردة ا