' AND e.kind = 'level' AND e.after_level = 1), 'فندق مملوك للشركة وبتقدم فيه خدمات كاملة للنزلاء. التصنيف:', '["IAS 40 لأنه بيجيب إيراد","IAS 16 لأن الخدمات جوهرية","IAS 2","IFRS 16"]', 1, 'الخدمات الجوهرية بتخلي العقار مستخدم بمعرفة المالك (IAS 40.12).' WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'ifrs' AND e.kind = 'level' AND e.after_level = 1) AND body = 'فندق مملوك للشركة وبتقدم فيه خدمات كاملة للنزلاء. التصنيف:'); INSERT INTO questions (exam_id, body, options, answer, explanation) SELECT (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'ifrs' AND e.kind = 'level' AND e.after_level = 1), 'شقق تملكها شركة تطوير عقاري ومعروضة للبيع. التصنيف:', '["مخزون حسب IAS 2","أصول ثابتة","استثمار عقاري","أصل غير ملموس"]', 0, 'IAS 40.9.' WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'ifrs' AND e.kind = 'level' AND e.after_level = 1) AND body = 'شقق تملكها شركة تطوير عقاري ومعروضة للبيع. التصنيف:'); INSERT INTO questions (exam_id, body, options, answer, explanation) SELECT (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'ifrs' AND e.kind = 'level' AND e.after_level = 1), 'عقار سعره 6,000,000، ورسوم نقل ملكية 240,000، وأتعاب محاماة 60,000، ومصاريف تسويق قبل تأجيره 50,000. التكلفة الأولية:', '["6,350,000 جنيه","6,000,000 جنيه","6,240,000 جنيه","6,300,000 جنيه"]', 3, '6,000,000 + 240,000 + 60,000 = 6,300,000. مصاريف بدء التشغيل مايدخلوش (IAS 40.21 و40.23).' WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'ifrs' AND e.kind = 'level' AND e.after_level = 1) AND body = 'عقار سعره 6,000,000، ورسوم نقل ملكية 240,000، وأتعاب محاماة 60,000، ومصاريف تسويق قبل تأجيره 50,000. التكلفة الأولية:'); INSERT INTO questions (exam_id, body, options, answer, explanation) SELECT (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'ifrs' AND e.kind = 'level' AND e.after_level = 1), 'بنموذج القيمة العادلة، العقار تكلفته 6,300,000 وقيمته العادلة آخر السنة 6,900,000. المعالجة:', '["600,000 فائض في OCI","600,000 مكسب في الأرباح والخسائر","مفيش قيد","900,000 مكسب"]', 1, 'IAS 40.35.' WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'ifrs' AND e.kind = 'level' AND e.after_level = 1) AND body = 'بنموذج القيمة العادلة، العقار تكلفته 6,300,000 وقيمته العادلة آخر السنة 6,900,000. المعالجة:'); INSERT INTO questions (exam_id, body, options, answer, explanation) SELECT (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'ifrs' AND e.kind = 'level' AND e.after_level = 1), 'بنفس العقار، السنة اللي بعدها القيمة العادلة 6,500,000. المعالجة:', '["مفيش قيد لأن القيمة لسه أعلى من التكلفة","تخفيض الفائض 400,000","إهلاك 400,000","خسارة 400,000 في الأرباح والخسائر"]', 3, '6,500,000 − 6,900,000 = (400,000) في الأرباح والخسائر.' WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'ifrs' AND e.kind = 'level' AND e.after_level = 1) AND body = 'بنفس العقار، السنة اللي بعدها القيمة العادلة 6,500,000. المعالجة:'); INSERT INTO questions (exam_id, body, options, answer, explanation) SELECT (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'ifrs' AND e.kind = 'level' AND e.after_level = 1), 'شركة عندها 5 عقارات استثمارية. سياسة القياس:', '["تختار نموذج لكل عقار","القيمة العادلة للأراضي والتكلفة للمباني","نموذج واحد لكل العقارات الاستثمارية","التكلفة دايمًا"]', 2, 'IAS 40.30 (مع استثناء محدود في 40.32A).' WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'ifrs' AND e.kind = 'level' AND e.after_level = 1) AND body = 'شركة عندها 5 عقارات استثمار